import{_ as a,o as s,c as t,a5 as i}from"./chunks/framework.a5no_H3L.js";const h=JSON.parse('{"title":"静态分析的方法与工具全景","description":"前四篇铺好了地基，本文开始进入实践：拿到一个陌生的 Windows 可执行文件，不运行它，怎么一步步摸清它在干什么。本文讲静态分析的方法论和工具全景，是后续 IDA、Ghidra 上手操作的引子，不假设你会用任何特定工具，只讲该按什么顺序看、每一步能得到什么。","frontmatter":{"type":"explanation","level":"intermediate"},"headers":[],"relativePath":"reverse-engineering/05-static-analysis/chapter-01-basics.md","filePath":"reverse-engineering/05-static-analysis/chapter-01-basics.md"}'),r={name:"reverse-engineering/05-static-analysis/chapter-01-basics.md"};function n(c,e,l,d,o,g){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="静态分析的方法与工具全景" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">静态分析的方法与工具全景 <a class="header-anchor" href="#静态分析的方法与工具全景" aria-label="Permalink to &quot;静态分析的方法与工具全景&quot;">​</a></h1><p data-src-line="4" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">前四篇铺好了地基，本文开始进入实践：拿到一个陌生的 Windows 可执行文件，不运行它，怎么一步步摸清它在干什么。本文讲静态分析的方法论和工具全景，是后续 IDA、Ghidra 上手操作的引子，不假设你会用任何特定工具，只讲该按什么顺序看、每一步能得到什么。</p><h2 id="_1-反汇编和反编译-不是一回事" tabindex="-1" data-src-line="6" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">1. 反汇编和反编译，不是一回事 <a class="header-anchor" href="#_1-反汇编和反编译-不是一回事" aria-label="Permalink to &quot;1. 反汇编和反编译，不是一回事&quot;">​</a></h2><p data-src-line="8" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">先澄清两个总被混用的词：</p><ul data-src-line="10" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><li data-src-line="10" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><strong>反汇编（disassembly）</strong>：把机器码翻译成汇编指令。结果忠实于机器码，但仍是底层语言。</li><li data-src-line="11" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><strong>反编译（decompilation）</strong>：把机器码进一步还原成类 C 的伪代码。结果更好读，但可能不精确、有猜测成分。</li></ul><p data-src-line="13" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">静态分析的日常工作，是在两者之间切换：<strong>用反编译伪代码快速理解逻辑，用反汇编核对细节</strong>。伪代码会骗人（比如错误推断类型、漏掉副作用），所以关键结论要回到反汇编里验证。这个「交叉验证」的习惯，比学会某个按钮重要得多。</p><h2 id="_2-第一步-识别文件类型与架构" tabindex="-1" data-src-line="15" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">2. 第一步：识别文件类型与架构 <a class="header-anchor" href="#_2-第一步-识别文件类型与架构" aria-label="Permalink to &quot;2. 第一步：识别文件类型与架构&quot;">​</a></h2><p data-src-line="17" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">别急着扔进反汇编器。先回答几个基础问题：这是什么文件？多少位？什么架构？加壳了吗？</p><p data-src-line="19" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">用<strong>文件识别工具</strong>先看一遍：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C:\\&gt; file target.exe</span></span>
<span class="line"><span>target.exe: PE32+ executable (GUI) x86-64, for MS Windows</span></span></code></pre></div><ul data-src-line="26" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><li data-src-line="26" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><code>PE32+</code> 是 64 位，<code>PE32</code> 是 32 位；<code>x86-64</code> 是架构；<code>GUI</code> / <code>console</code> 是子系统（有无控制台窗口）。</li><li data-src-line="27" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><strong>Detect It Easy（DIE）</strong> 是更专业的 PE 识别工具，还能判断编译器、是否加壳。这一行信息能立刻帮你决定后面用什么方法：32 位程序用 32 位工具，加壳的程序要先处理壳（<a href="./../07-packing/chapter-01-packing-principle.html">加壳与脱壳</a>）。</li></ul><p data-src-line="29" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">判断是否加壳的快速信号：节区名异常（如 <code>UPX0</code>、<code>UPX1</code>、<code>.packed</code>）、入口点落在非 <code>.text</code> 节、节区 <code>SizeOfRawData</code> 远小于 <code>VirtualSize</code>、DIE 直接报出壳名。看到这些，先别反汇编，去<a href="./../07-packing/chapter-01-packing-principle.html">加壳与脱壳</a>。</p><h2 id="_3-第二步-看元信息与字符串" tabindex="-1" data-src-line="31" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">3. 第二步：看元信息与字符串 <a class="header-anchor" href="#_3-第二步-看元信息与字符串" aria-label="Permalink to &quot;3. 第二步：看元信息与字符串&quot;">​</a></h2><p data-src-line="33" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">用 PE 查看工具（PE-bear、CFF Explorer，或微软自带的 <code>dumpbin</code>）打开文件，重点看：</p><ul data-src-line="35" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><li data-src-line="35" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><strong>节区列表</strong>：有哪些节、权限如何，对程序结构有个印象。</li><li data-src-line="36" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><strong>导入表 / 导出表</strong>：这是「程序想干什么」的第一线索（<a href="./../04-pe-format/chapter-02-address-and-tables.html">PE 文件格式</a>已讲）。</li></ul><p data-src-line="38" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">接着用<strong>字符串提取</strong>看程序里嵌的可读文本：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C:\\&gt; strings target.exe</span></span></code></pre></div><p data-src-line="44" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">字符串常包含关键信息：URL、文件路径、注册表键、错误提示、加密算法名、密钥等。一个有 <code>https://...</code> 和 <code>POST</code> 的程序很可能要联网；出现 <code>license</code>、<code>trial</code> 字样的可能涉及授权逻辑。字符串分析成本极低，却常常直接给出突破口。</p><blockquote data-src-line="46" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><p data-src-line="46" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><code>strings</code> 在 Linux/macOS 原生可用，Windows 上可用 Sysinternals 的 <code>strings.exe</code>，或直接在反汇编器里看字符串视图。不要用字符串内容替代真正的行为分析——它只是线索，不是结论。</p></blockquote><h2 id="find-main" tabindex="-1" data-src-line="48" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">4. 第三步：定位入口，找到真正的 main <a class="header-anchor" href="#find-main" aria-label="Permalink to &quot;4. 第三步：定位入口，找到真正的 main {#find-main}&quot;">​</a></h2><p data-src-line="50" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">PE 的 <code>AddressOfEntryPoint</code> 指向的是<strong>真正入口点（entry point）</strong>，但它通常不是 <code>main</code>。C/C++ 程序在 <code>main</code> 之前要跑一段运行时初始化（CRT 初始化、构造全局对象等），所以入口点先进入 CRT 代码，再由它调用 <code>main</code>。</p><p data-src-line="52" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">要找到 <code>main</code>，方法有几种：</p><ul data-src-line="54" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><li data-src-line="54" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">反汇编器通常会自动识别，把入口点函数标成 <code>start</code>，并提示哪里是 <code>main</code>。</li><li data-src-line="55" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">从入口点函数往下追，找它 <code>call</code> 的那个被传入 <code>__argc</code>、<code>__argv</code> 的函数（x64 上 <code>main</code> 的参数是 <code>RCX</code>（argc）、<code>RDX</code>（argv））。</li><li data-src-line="56" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">有符号（PDB）的程序，反汇编器直接显示函数名，<code>main</code> 一眼可见。</li></ul><p data-src-line="58" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">对逆向来说，<strong>你真正要分析的是 <code>main</code> 及其调用的业务逻辑，而不是 CRT 初始化代码</strong>。初学常犯的错，是盯着入口点的 CRT 代码看半天，其实那是每个程序都一样的模板。</p><h2 id="_5-第四步-读反汇编-伪代码" tabindex="-1" data-src-line="60" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">5. 第四步：读反汇编 / 伪代码 <a class="header-anchor" href="#_5-第四步-读反汇编-伪代码" aria-label="Permalink to &quot;5. 第四步：读反汇编 / 伪代码&quot;">​</a></h2><p data-src-line="62" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">定位到 <code>main</code> 后，开始真正的阅读。结合<a href="./../02-assembly/chapter-02-x64-assembly.html">x64 汇编</a>的知识，按这个节奏：</p><ol data-src-line="64" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><li data-src-line="64" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><strong>先看函数级视图</strong>：反汇编器会把函数列出来。扫一遍函数名（如果有符号）和大小，形成「这个程序由哪些函数组成」的印象。</li><li data-src-line="65" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><strong>看导入函数调用</strong>：在反汇编里找 <code>call &lt;导入函数&gt;</code>，反汇编器会标注名字。这是最快理解「程序在做哪类操作」的路径。</li><li data-src-line="66" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><strong>用反编译器生成伪代码</strong>：把 <code>main</code> 反编译成类 C 代码，逻辑立刻清晰很多。</li><li data-src-line="67" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><strong>交叉引用（xref）</strong>：对感兴趣的数据（如某个字符串）查「谁引用了它」，能反推程序的判断逻辑藏在哪。</li><li data-src-line="68" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><strong>关键判断处核对反汇编</strong>：伪代码里的 <code>if</code>、循环，回到反汇编看 <code>cmp + jcc</code>，确认没被反编译器误导。</li></ol><p data-src-line="70" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><a href="./chapter-04-ida-pro.html">IDA Pro</a> 和 <a href="./chapter-05-ghidra.html">Ghidra</a> 会把这些动作落到具体操作上。</p><h2 id="_6-工具全景-静态分析用哪些" tabindex="-1" data-src-line="72" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">6. 工具全景：静态分析用哪些 <a class="header-anchor" href="#_6-工具全景-静态分析用哪些" aria-label="Permalink to &quot;6. 工具全景：静态分析用哪些&quot;">​</a></h2><p data-src-line="74" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">静态分析工具按用途分层，从轻到重：</p><table tabindex="0"><thead data-src-line="76" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><tr data-src-line="76" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><th style="text-align:left;">层</th><th style="text-align:left;">工具</th><th style="text-align:left;">用途</th></tr></thead><tbody data-src-line="78" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><tr data-src-line="78" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><td style="text-align:left;">文件识别</td><td style="text-align:left;">Detect It Easy、<code>file</code></td><td style="text-align:left;">判架构、判壳、判编译器</td></tr><tr data-src-line="79" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><td style="text-align:left;">文件结构查看</td><td style="text-align:left;">PE-bear、CFF Explorer、<code>dumpbin</code></td><td style="text-align:left;">看节区、导入导出、重定位</td></tr><tr data-src-line="80" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><td style="text-align:left;">字符串提取</td><td style="text-align:left;"><code>strings</code>、反汇编器内置</td><td style="text-align:left;">快速找线索</td></tr><tr data-src-line="81" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><td style="text-align:left;">反汇编</td><td style="text-align:left;">IDA Pro、Ghidra、Binary Ninja、objdump</td><td style="text-align:left;">读机器码翻译</td></tr><tr data-src-line="82" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><td style="text-align:left;">反编译</td><td style="text-align:left;">IDA Pro（Hex-Rays）、Ghidra</td><td style="text-align:left;">还原伪代码</td></tr></tbody></table><p data-src-line="84" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">其中 <strong>IDA Pro</strong> 和 <strong>Ghidra</strong> 是这一章的主角，两者的定位如下：</p><ul data-src-line="86" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><li data-src-line="86" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><strong>IDA Pro</strong>：商业付费，交互体验、分析深度、脚本生态（IDAPython）和插件最成熟，是安全行业的实际标准。反编译器（Hex-Rays Decompiler）单独付费。当前主流版本为 8.x 和 9.x（见官方 <a href="https://docs.hex-rays.com/release-notes/" target="_blank" rel="noreferrer">release notes</a>）。</li><li data-src-line="87" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><strong>Ghidra</strong>：NSA 开源免费，反编译能力很强，自带反编译器（这点对入门很友好，不用额外付费），支持多平台，还能写 Java/Python 脚本自动化分析。当前版本约 11.x～12.x（见官方 <a href="https://ghidra-sre.org/" target="_blank" rel="noreferrer">release notes</a>）。</li></ul><p data-src-line="89" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><strong>入门建议：用 Ghidra 起步，把方法学会；如果之后从事专业逆向工作，再上 IDA Pro。</strong> 两者的核心概念（函数、交叉引用、反编译、命名重命名）几乎一一对应，学会一个，另一个上手很快。</p><hr><blockquote data-src-line="93" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md"><p data-src-line="93" data-src-file="reverse-engineering/05-static-analysis/chapter-01-basics.md">本章建立的是静态分析的工作流：先识别文件类型与架构，再看元信息与字符串，然后定位 <code>main</code>，最后读反汇编与伪代码；反汇编与反编译互为验证。下一章把这条流程落到具体工具——<a href="./chapter-04-ida-pro.html">IDA Pro</a>。</p></blockquote>`,36)])])}const m=a(r,[["render",n]]);export{h as __pageData,m as default};
